-- 0002: application tables (doc §7, plus `products`).
--
-- Conventions
--   * ids are uuid, generated by the database
--   * money is bigint minor units (paise) in *_amount_minor columns, never negative
--   * status columns are limited to known values with CHECK constraints
--   * timestamps are timestamptz

-- ---------------------------------------------------------------------------
-- Customers and catalogue
-- ---------------------------------------------------------------------------

create table app.customers (
    id                    uuid primary key default gen_random_uuid(),
    -- Supabase Auth user id (JWT `sub`). Null until the customer has a login.
    external_auth_subject uuid unique,
    name                  text not null,
    email                 text not null,
    created_at            timestamptz not null default now()
);
create unique index customers_email_key on app.customers (lower(email));

create table app.products (
    id         uuid primary key default gen_random_uuid(),
    name       text not null,
    category   text not null,
    created_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Orders, items, returns
-- ---------------------------------------------------------------------------

create table app.orders (
    id                    uuid primary key default gen_random_uuid(),
    customer_id           uuid not null references app.customers (id),
    status                text not null
        check (status in ('placed', 'shipped', 'delivered', 'cancelled')),
    currency              char(3) not null default 'INR',
    paid_amount_minor     bigint not null check (paid_amount_minor >= 0),
    -- Refund accounting (doc §7): money already refunded, and money held by
    -- refund operations that are in flight. Together they can never exceed
    -- what the customer paid.
    refunded_amount_minor bigint not null default 0 check (refunded_amount_minor >= 0),
    reserved_amount_minor bigint not null default 0 check (reserved_amount_minor >= 0),
    placed_at             timestamptz not null default now(),
    delivered_at          timestamptz,
    created_at            timestamptz not null default now(),
    constraint orders_refunds_within_paid
        check (refunded_amount_minor + reserved_amount_minor <= paid_amount_minor),
    constraint orders_delivered_has_timestamp
        check (status <> 'delivered' or delivered_at is not null)
);
create index orders_customer_id_idx on app.orders (customer_id);

create table app.order_items (
    id                uuid primary key default gen_random_uuid(),
    order_id          uuid not null references app.orders (id) on delete cascade,
    product_id        uuid not null references app.products (id),
    quantity          integer not null check (quantity > 0),
    paid_amount_minor bigint not null check (paid_amount_minor >= 0)
);
create index order_items_order_id_idx on app.order_items (order_id);
create index order_items_product_id_idx on app.order_items (product_id);

create table app.returns (
    id                uuid primary key default gen_random_uuid(),
    order_id          uuid not null references app.orders (id),
    status            text not null
        check (status in ('requested', 'in_transit', 'received', 'rejected', 'closed')),
    received_at       timestamptz,
    inspection_status text not null default 'not_inspected'
        check (inspection_status in ('not_inspected', 'passed', 'failed')),
    created_at        timestamptz not null default now(),
    constraint returns_received_has_timestamp
        check (status <> 'received' or received_at is not null)
);
create index returns_order_id_idx on app.returns (order_id);

-- ---------------------------------------------------------------------------
-- Tickets and workflow runs
-- ---------------------------------------------------------------------------

create table app.tickets (
    id          uuid primary key default gen_random_uuid(),
    customer_id uuid not null references app.customers (id),
    order_id    uuid references app.orders (id),
    category    text not null
        check (category in ('order_status', 'refund_request', 'damaged_item', 'other')),
    status      text not null default 'open'
        check (status in ('open', 'in_progress', 'awaiting_approval', 'escalated', 'resolved', 'closed')),
    summary     text not null,
    created_at  timestamptz not null default now(),
    updated_at  timestamptz not null default now()
);
create index tickets_customer_id_idx on app.tickets (customer_id);
create index tickets_order_id_idx on app.tickets (order_id);

create table app.workflow_runs (
    id           uuid primary key default gen_random_uuid(),
    ticket_id    uuid not null references app.tickets (id),
    -- LangGraph thread id; links this run to its checkpoints in `langgraph`.
    thread_id    text not null unique,
    status       text not null default 'running'
        check (status in ('running', 'awaiting_approval', 'completed', 'failed', 'cancelled')),
    started_at   timestamptz not null default now(),
    completed_at timestamptz
);
create index workflow_runs_ticket_id_idx on app.workflow_runs (ticket_id);

-- ---------------------------------------------------------------------------
-- Policies (RAG)
-- ---------------------------------------------------------------------------

create table app.policy_documents (
    id             uuid primary key default gen_random_uuid(),
    title          text not null,
    version        text not null,
    effective_from date not null,
    effective_to   date,
    source_uri     text not null,
    created_at     timestamptz not null default now(),
    unique (source_uri, version),
    constraint policy_documents_valid_range
        check (effective_to is null or effective_to > effective_from)
);

create table app.policy_chunks (
    id          uuid primary key default gen_random_uuid(),
    document_id uuid not null references app.policy_documents (id) on delete cascade,
    chunk_index integer not null check (chunk_index >= 0),
    content     text not null,
    -- text-embedding-3-small; filled in by policy ingestion (week 2).
    embedding   extensions.vector(1536),
    metadata    jsonb not null default '{}'::jsonb,
    unique (document_id, chunk_index)
);

-- ---------------------------------------------------------------------------
-- Proposals, approvals, refunds
-- ---------------------------------------------------------------------------

create table app.action_proposals (
    id           uuid primary key default gen_random_uuid(),
    run_id       uuid not null references app.workflow_runs (id),
    action_type  text not null
        check (action_type in ('refund', 'escalate', 'no_action')),
    payload      jsonb not null,
    -- sha256 hex of the canonical payload; approvals are bound to it.
    payload_hash text not null check (payload_hash ~ '^[0-9a-f]{64}$'),
    status       text not null default 'pending_approval'
        check (status in ('pending_approval', 'approved', 'rejected', 'expired', 'invalidated', 'executed')),
    created_at   timestamptz not null default now(),
    -- Target for the approvals foreign key below.
    unique (id, payload_hash)
);
create index action_proposals_run_id_idx on app.action_proposals (run_id);

create table app.approvals (
    id            uuid primary key default gen_random_uuid(),
    proposal_id   uuid not null,
    -- The exact proposal version this approval is for (doc §7). The composite
    -- foreign key means it must equal the proposal's payload_hash.
    payload_hash  text not null,
    -- Supabase Auth user id of the reviewer; set when the decision is made.
    reviewer_id   uuid,
    decision      text not null default 'pending'
        check (decision in ('pending', 'approved', 'rejected')),
    expires_at    timestamptz not null,
    decided_at    timestamptz,
    created_at    timestamptz not null default now(),
    foreign key (proposal_id, payload_hash)
        references app.action_proposals (id, payload_hash),
    constraint approvals_decision_complete check (
        (decision = 'pending'  and reviewer_id is null     and decided_at is null) or
        (decision <> 'pending' and reviewer_id is not null and decided_at is not null)
    ),
    constraint approvals_expiry_after_creation check (expires_at > created_at)
);
create index approvals_proposal_id_idx on app.approvals (proposal_id);
-- At most one open approval per proposal.
create unique index approvals_one_pending_per_proposal
    on app.approvals (proposal_id) where decision = 'pending';

create table app.refund_operations (
    id                 uuid primary key default gen_random_uuid(),
    order_id           uuid not null references app.orders (id),
    -- One refund per approved proposal, so re-running it can't refund twice.
    proposal_id        uuid not null unique references app.action_proposals (id),
    approval_id        uuid not null references app.approvals (id),
    amount_minor       bigint not null check (amount_minor > 0),
    currency           char(3) not null default 'INR',
    -- Sent to the payment provider; the same key always means the same refund.
    idempotency_key    text not null unique,
    -- sha256 hex of the request body, to detect a changed payload under the same key.
    request_hash       text not null check (request_hash ~ '^[0-9a-f]{64}$'),
    provider_reference text unique,
    status             text not null default 'reserved'
        check (status in ('reserved', 'submitted', 'succeeded', 'failed', 'pending_reconciliation')),
    created_at         timestamptz not null default now(),
    updated_at         timestamptz not null default now()
);
create index refund_operations_order_id_idx on app.refund_operations (order_id);

-- ---------------------------------------------------------------------------
-- Audit log
-- ---------------------------------------------------------------------------

create table app.audit_events (
    id               uuid primary key default gen_random_uuid(),
    run_id           uuid references app.workflow_runs (id),
    actor            text not null,
    event_type       text not null,
    redacted_payload jsonb not null default '{}'::jsonb,
    created_at       timestamptz not null default now()
);
create index audit_events_run_id_created_at_idx on app.audit_events (run_id, created_at);

-- ---------------------------------------------------------------------------
-- Immutability: proposals can't be edited once written (doc §11) and the
-- audit log is append-only.
-- ---------------------------------------------------------------------------

create function app.reject_proposal_edit() returns trigger
language plpgsql as $$
begin
    if new.run_id       is distinct from old.run_id
    or new.action_type  is distinct from old.action_type
    or new.payload      is distinct from old.payload
    or new.payload_hash is distinct from old.payload_hash then
        raise exception 'action_proposals are immutable; create a new proposal instead';
    end if;
    return new;  -- status changes are allowed
end;
$$;

create trigger action_proposals_immutable
    before update on app.action_proposals
    for each row execute function app.reject_proposal_edit();

create function app.reject_audit_change() returns trigger
language plpgsql as $$
begin
    raise exception 'audit_events is append-only';
end;
$$;

create trigger audit_events_append_only
    before update or delete on app.audit_events
    for each row execute function app.reject_audit_change();
